"""gRPC server interceptors: MetricsInterceptor, RateLimitInterceptor, AuditInterceptor, AuthInterceptor."""
import logging
import threading
import time
from contextlib import contextmanager

import grpc
import jwt
from prometheus_client import Counter, Histogram

from app.auth import _verify


def _wrap(handler, around):
    """Run the handler inside the around(context) context manager, whatever its kind.

    Response-streaming handlers are wrapped as generators so around() spans the
    whole stream (final status, full latency), not just the call that creates it.
    """
    if handler is None:
        return None

    def unary(inner):
        def call(request, context):
            with around(context):
                return inner(request, context)
        return call

    def streaming(inner):
        def call(request, context):
            with around(context):
                yield from inner(request, context)
        return call

    return handler._replace(
        unary_unary=handler.unary_unary and unary(handler.unary_unary),
        stream_unary=handler.stream_unary and unary(handler.stream_unary),
        unary_stream=handler.unary_stream and streaming(handler.unary_stream),
        stream_stream=handler.stream_stream and streaming(handler.stream_stream),
    )


def _peer(context) -> str:
    """Client address without the port ("ipv4:10.0.0.1:5123" -> "ipv4:10.0.0.1")."""
    return context.peer().rsplit(":", 1)[0]


def _status(context, failed: bool) -> str:
    code = context.code()
    if code is not None:
        return code.name
    return "UNKNOWN" if failed else "OK"


_RPCS = Counter("grpc_server_handled_total", "RPCs completed on the server, by method and status code.", ["grpc_method", "grpc_code"])
_SECONDS = Histogram("grpc_server_handling_seconds", "RPC latency on the server, by method.", ["grpc_method"])


class MetricsInterceptor(grpc.ServerInterceptor):
    """Per-RPC count + latency; app.main serves them on METRICS_PORT."""

    def intercept_service(self, continuation, handler_call_details):
        method = handler_call_details.method

        @contextmanager
        def around(context):
            start = time.perf_counter()
            failed = False
            try:
                yield
            except Exception:
                failed = True
                raise
            finally:
                _SECONDS.labels(method).observe(time.perf_counter() - start)
                _RPCS.labels(method, _status(context, failed)).inc()

        return _wrap(continuation(handler_call_details), around)


class RateLimitInterceptor(grpc.ServerInterceptor):
    """Rejects RPCs with RESOURCE_EXHAUSTED past 60 / minute / client.

    ponytail: in-memory fixed window, per process. Move the counters to Redis
    if the limit must hold across replicas.
    """

    def __init__(self, limit: int = 60, window: float = 60.0):
        self._limit = limit
        self._window = window
        self._hits: dict[str, tuple[int, float]] = {}
        self._lock = threading.Lock()

    def _allow(self, key: str) -> bool:
        now = time.monotonic()
        with self._lock:
            count, reset_at = self._hits.get(key, (0, now + self._window))
            if reset_at < now:
                count, reset_at = 0, now + self._window
            if count >= self._limit:
                return False
            self._hits[key] = (count + 1, reset_at)
            return True

    def intercept_service(self, continuation, handler_call_details):
        # ponytail: one hit per RPC (a stream counts once), not per message.
        @contextmanager
        def around(context):
            if not self._allow(_peer(context)):
                context.abort(grpc.StatusCode.RESOURCE_EXHAUSTED, "rate_limited")
            yield

        return _wrap(continuation(handler_call_details), around)


class AuditInterceptor(grpc.ServerInterceptor):
    """One structured log line per RPC."""

    _log = logging.getLogger("audit")

    def intercept_service(self, continuation, handler_call_details):
        method = handler_call_details.method

        @contextmanager
        def around(context):
            failed = False
            try:
                yield
            except Exception:
                failed = True
                raise
            finally:
                self._log.info("audit", extra={
                    "event": "audit",
                    "method": method,
                    "code": _status(context, failed),
                    "peer": _peer(context),
                })

        return _wrap(continuation(handler_call_details), around)


# Entity RPCs whose REST routes require auth.
PROTECTED_RPCS = frozenset({
    "/test_app.v1.UserService/ListUser",
    "/test_app.v1.UserService/GetUser",
    "/test_app.v1.UserService/CreateUser",
    "/test_app.v1.UserService/DeleteUser",
})


def _deny(code: grpc.StatusCode, details: str):
    def abort(_request, context):
        context.abort(code, details)

    return grpc.unary_unary_rpc_method_handler(abort)


class AuthInterceptor(grpc.ServerInterceptor):
    """Requires a valid bearer token in the "authorization" metadata for
    PROTECTED_RPCS, checked by the same verifier (app.auth) as the REST routes."""

    def intercept_service(self, continuation, handler_call_details):
        if handler_call_details.method not in PROTECTED_RPCS:
            return continuation(handler_call_details)
        metadata = dict(handler_call_details.invocation_metadata or ())
        authorization = metadata.get("authorization", "")
        if not authorization.startswith("Bearer "):
            return _deny(grpc.StatusCode.UNAUTHENTICATED, "missing_or_malformed_token")
        try:
            _verify(authorization[len("Bearer "):].strip())
        except jwt.PyJWTError:  # bad token, or JWKS fetch failure
            return _deny(grpc.StatusCode.UNAUTHENTICATED, "invalid_token")
        except RuntimeError:
            return _deny(grpc.StatusCode.INTERNAL, "auth_unconfigured")
        return continuation(handler_call_details)

