"""PostService: CRUD over the SQLAlchemy model the REST routers use (app.models)."""
import uuid

import grpc
from google.protobuf import empty_pb2
from sqlalchemy.exc import IntegrityError

from app.db import SessionLocal
from app.models import Post
from app.services.common import page_of, require
from test_app.v1 import service_pb2, service_pb2_grpc


def _to_pb(m: Post) -> service_pb2.Post:
    out = service_pb2.Post(
        id=str(m.id) if m.id is not None else "",
        title=m.title or "",
        body=m.body or "",
        published=bool(m.published),
    )
    if m.created_at is not None:
        out.created_at.FromDatetime(m.created_at)
    if m.updated_at is not None:
        out.updated_at.FromDatetime(m.updated_at)
    return out


def _create_values(request, context) -> dict:
    values = {
        "title": request.title or None,
        "body": request.body or None,
        "published": request.published,
    }
    require(values, ("title", "body"), context)
    return values


def _update_values(request, context) -> dict:
    """UpdatePost replaces every field (the proto has no field mask)."""
    values = {
        "title": request.title or None,
        "body": request.body or None,
        "published": request.published,
    }
    require(values, ("title", "body"), context)
    return values


def _get(db, request, context) -> Post:
    if not request.id:
        context.abort(grpc.StatusCode.INVALID_ARGUMENT, "id is required")
    try:
        key = uuid.UUID(request.id)
    except ValueError:
        context.abort(grpc.StatusCode.INVALID_ARGUMENT, "id must be a UUID")
    item = db.get(Post, key)
    if item is None:
        context.abort(grpc.StatusCode.NOT_FOUND, "not found")
    return item


def _commit(db, context) -> None:
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        context.abort(grpc.StatusCode.ALREADY_EXISTS, "already exists")


class PostService(service_pb2_grpc.PostServiceServicer):
    def ListPost(self, request, context):
        page, size = page_of(request)
        with SessionLocal() as db:
            total = db.query(Post).count()
            rows = db.query(Post).order_by(Post.id).offset((page - 1) * size).limit(size).all()
            return service_pb2.ListPostResponse(items=[_to_pb(m) for m in rows], total=total, page=page, page_size=size)

    def GetPost(self, request, context):
        with SessionLocal() as db:
            return _to_pb(_get(db, request, context))

    def CreatePost(self, request, context):
        item = Post(**_create_values(request, context))
        with SessionLocal() as db:
            db.add(item)
            _commit(db, context)
            db.refresh(item)
            return _to_pb(item)

    def UpdatePost(self, request, context):
        values = _update_values(request, context)
        with SessionLocal() as db:
            item = _get(db, request, context)
            for k, v in values.items():
                setattr(item, k, v)
            _commit(db, context)
            db.refresh(item)
            return _to_pb(item)

    def DeletePost(self, request, context):
        with SessionLocal() as db:
            db.delete(_get(db, request, context))
            _commit(db, context)
            return empty_pb2.Empty()

